package com.example.inventory;
import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class ForecastClient{private final String base;private final HttpClient h=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();public ForecastClient(String b){base=b.replaceAll("/$","");}public String forecast(Item x)throws Exception{var q=HttpRequest.newBuilder(URI.create(base+"/v1/forecast")).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(x.json())).build();var r=h.send(q,HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new IllegalStateException(r.body());return r.body();}public static void main(String[]a)throws Exception{System.out.println(new ForecastClient(a.length>0?a[0]:"http://127.0.0.1:8000").forecast(new Item("SKU-001",1,1,0,60,1.1)));}public record Item(String sku,double price,int promo,int stock,double recent,double season){String json(){return String.format("{\"sku_id\":\"%s\",\"price_index\":%.3f,\"promo_active\":%d,\"stockout_days\":%d,\"recent_week_units\":%.2f,\"season_index\":%.3f}",sku,price,promo,stock,recent,season);}}}
